            int result = 0;
            for (; x; x /= 3) {
                result += x % 3;
            }
            return result;
        };

        vector<int> dp(pow(3, numSlots));
        for (int mask = 1; mask < size(dp); ++mask) {
            const int i = count(mask) - 1;
