// Time:  O(nlogn + n * k)
// Space: O(n * k)

class Solution {
public:
    int maxValue(vector<vector<int>>& events, int k) {
        sort(begin(events), end(events),
             [](const auto& a, const auto& b) {
                 return a[1] < b[1];
             });
        vector<vector<int>> dp(size(events) + 1, vector<int>(k + 1));
        for (int i = 1; i <= size(events); ++i) {
            auto prev_i_m_1 = distance(cbegin(events),
                                       prev(lower_bound(cbegin(events), cend(events), events[i - 1],
                                            [](const auto& a, const auto& b) {
                                                return a[1] < b[0];
                                            })));
            for (int j = 1; j <= k; ++j) {
                dp[i][j] = max(dp[i - 1][j], dp[prev_i_m_1 + 1][j - 1] + events[i - 1][2]);
            }
        }
        return dp[size(events)][k];
    }
};

// Time:  O(nlogn + n * k)
// Space: O(n * k)
class Solution2 {
public:
    int maxValue(vector<vector<int>>& events, int k) {
        sort(begin(events), end(events));
        vector<vector<int>> dp(size(events) + 1, vector<int>(k + 1));
        for (int i = size(events) - 1; i >= 0; --i) {
            auto next_i = distance(cbegin(events),
                                   prev(upper_bound(cbegin(events), cend(events), events[i],
                                        [](const auto& a, const auto& b) {
                                            return a[1] < b[0];
                                        })));
            for (int j = 1; j <= k; ++j) {
                dp[i][j] = max(dp[i + 1][j], dp[next_i + 1][j - 1] + events[i][2]);
            }
        }
        return dp[0][k];
    }
};

// Time:  O(r + nlogn), r is the max end day of events
// Space: O(n)

class Solution {
public:
    int maxEvents(vector<vector<int>>& events) {
        sort(events.begin(), events.end(), greater<vector<int>>());
        const auto max_day = (*max_element(events.cbegin(), events.cend(),
                                           [](const auto& a, const auto& b) {
                                               return a[1] < b[1];
                                           }))[1];
        priority_queue<int, vector<int>, greater<int>> min_heap;
        int result = 0;
        for (int d = 1; d <= max_day; ++d) {
            while (!events.empty() && events.back()[0] == d) {
                min_heap.emplace(events.back()[1]);
                events.pop_back();
            }
            while (!min_heap.empty() && min_heap.top() == d - 1) {
                min_heap.pop();
            }
            if (min_heap.empty()) {
                continue;
            }
            min_heap.pop();
            ++result;
        }
        return result;
    }
};

