            }
            vector<int64_t> new_dp(size(points[i]));
            for (int j = 0; j < size(points[i]); ++j) {
                new_dp[j] = max(prefix[j] - j, suffix[j] + j) + points[i][j];
            }
            dp = move(new_dp);
        }
        return *max_element(cbegin(dp), cend(dp));
    }
};

