// Time:  O(n)
// Space: O(n)

// union find
class Solution {
public:
    int maxActivated(vector<vector<int>>& points) {
        static const int N_DIM = 2;
        static const int N_ADD = 1;

        UnionFind uf(size(points));
        vector<unordered_map<int, int>> lookup(N_DIM);
        for (int i = 0; i < size(points); ++i) {
            for (int j = 0; j < size(lookup); ++j) {
                if (lookup[j].count(points[i][j])) {
                    uf.union_set(i, lookup[j][points[i][j]]);
                } else {
                    lookup[j][points[i][j]] = i;
                }
            }
        }
        vector<int> top(min(N_ADD + 1, static_cast<int>(size(points))));
        for (int i = 0; i < size(points); ++i) {
            if (uf.find_set(i) != i) {
                continue;
            }
            for (int j = 0, s = uf.total(i); j < size(top); ++j) {
                if (s > top[j]) {
                    swap(top[j], s);
                }
            }
        }
        return accumulate(cbegin(top), cend(top), 0) + N_ADD;
     }

private:
    class UnionFind {
    public:
        UnionFind(int n)
         : set_(n)
         , rank_(n)
         , size_(n, 1)  {
            iota(set_.begin(), set_.end(), 0);
        }

        int find_set(int x) {
           vector<int> stk;
            while (set_[x] != x) {  // path compression
                stk.emplace_back(x);
                x = set_[x];
            }
            while (!empty(stk)) {
                const int y = stk.back(); stk.pop_back();
                set_[y] = x;
            }
            return x;
        }

        bool union_set(int x, int y) {
            x = find_set(x), y = find_set(y);
            if (x == y) {
                return false;
            }
            if (rank_[x] > rank_[y]) {
                swap(x, y);
            } else if (rank_[x] == rank_[y]) {
                ++rank_[y];
            }
            set_[x] = y;  // Union by rank.
            size_[y] += size_[x];
            return true;
        }

        int64_t total(int x) {
            return size_[find_set(x)];
        }

    private:
        vector<int> set_;
        vector<int> rank_;
        vector<int64_t> size_;
    };
};

kamyu-c-maximum-points-after-collecting-:
// Time:  O(nlogr), r = max(coins)
// Space: O(n)

// dfs, bitmasks, pruning
class Solution {
public:
    int maximumPoints(vector<vector<int>>& edges, vector<int>& coins, int k) {
        static const int NEG_INF = numeric_limits<int>::min();

        vector<vector<int>> adj(size(coins));
        for (const auto& e : edges) {
            adj[e[0]].emplace_back(e[1]);
            adj[e[1]].emplace_back(e[0]);
        }
        const int mx = *max_element(cbegin(coins), cend(coins));
        const int max_base = 1 << (mx != 0 ? __lg(mx) + 1 : 0);
        vector<int> lookup(size(coins));
        const function<int (int, int, int)> dfs = [&](int u, int p, int base) {
            if (base >= max_base) {
                return 0;
            }
            if (lookup[u] & base) {  // we prefer the first way to the second way, so the visited state cannot improve the current chosen ways
                return NEG_INF;
            }
            lookup[u] |= base;
            int total1 = (coins[u] / base) - k;
            for (const auto& v : adj[u]) {
                if (v == p) {
                    continue;
                }
                const auto& r = dfs(v, u, base);
                if (r == NEG_INF) {
                    total1 = r;
                    break;
                }
                total1 += r;
            }
            if ((coins[u] / base) - k >= coins[u] / (base << 1)) {  // if (coins[u]//base)-k >= coins[u]//(base*2), the first way is always better
                return total1;
            }
            int total2 = coins[u] / (base << 1);
            for (const auto& v : adj[u]) {
                if (v == p) {
                    continue;
                }
                const auto& r = dfs(v, u, base << 1);
                if (r == NEG_INF) {
                    total2 = r;
                    break;
                }
                total2 += r;
            }
            return max(total1, total2);
        };

        return dfs(0, -1, 1);
    }
};

// Time:  O(nlogr), r = max(coins)
// Space: O(nlogr)
// tree dp, memoization
class Solution2 {
public:
    int maximumPoints(vector<vector<int>>& edges, vector<int>& coins, int k) {
        vector<vector<int>> adj(size(coins));
        for (const auto& e : edges) {
            adj[e[0]].emplace_back(e[1]);
            adj[e[1]].emplace_back(e[0]);
        }
        const int mx =  *max_element(cbegin(coins), cend(coins));
        const int max_d = mx != 0 ? __lg(mx) + 1 : 0;
        vector<vector<int>> lookup(size(coins), vector<int>(max_d, -1));
        const function<int (int, int, int)> memoization = [&](int u, int p, int d) {
            if (d >= max_d) {
                return 0;
            }
            if (lookup[u][d] == -1) {
                int total1 = (coins[u] >> d) - k;
                for (const auto& v : adj[u]) {
                    if (v != p) {
                        total1 += memoization(v, u, d);
                    }
                }
                int total2 = coins[u] >> (d + 1);
                for (const auto& v : adj[u]) {
                    if (v != p) {
                        total2 += memoization(v, u, d + 1);
                    }
                }
                lookup[u][d] = max(total1, total2);
            }
            return lookup[u][d];
        };

        return memoization(0, -1, 0);
    }
};

