            for (; x; x >>= 1) {
                result.push_back(x & 1 ? '1' : '0');
            }
            reverse(begin(result), end(result));
            return result;
        };

        vector<int> idxs(size(nums));
        iota(begin(idxs), end(idxs), 0);
        int result = 0;
