class Solution {
public:
    long long maxProduct(vector<int>& nums) {
        const auto& bit_length = [](int x) {
            return (x ? std::__lg(x) : -1) + 1;
        };

        const auto& l = bit_length(ranges::max(nums));
        vector<int> dp(1 << l);
        for (const auto& x : nums) {
            dp[x] = x;
