        for (int i = 0; i < l; ++i) {
            for (int j = 0; j < (1 << l); j += 1 << (i + 1)) {
                for (int k = j; k < j + (1 << i); ++k) {
                    if (dp[k] > dp[k + (1 << i)]) {
                        dp[k + (1 << i)] = dp[k];
                    }
                }
            }
        }
        int64_t result = 0;
        for (const auto& x : nums) {
            const auto& v = static_cast<int64_t>(x) * dp[((1 << l) - 1) ^ x];
            if (v > result) {
                result = v;
            }
        }
        return result;
    }
};

