// dp, bitmasks
class Solution {
public:
    int maxProfit(int n, vector<vector<int>>& edges, vector<int>& score) {
        vector<int> adj(n);
        for (const auto& e : edges) {
            adj[e[1]] |= 1 << e[0];
        }
        vector<int> dp(1 << n, -1);
        dp[0] = 0;
        for (int mask = 0; mask < size(dp); ++mask) {
            if (dp[mask] == -1) {
                continue;
