        }
        int result = NEG_INF;
        const auto& fn = [](int a, int b) {
            return max(a, b);
        };
        BIT bit1(size(price_to_idx), NEG_INF, fn), bit2(size(price_to_idx), NEG_INF, fn);
        for (int i = 0; i < size(prices); ++i) {
