kamyu-c-maximum-score-of-spliced-array-1:
// Time:  O(n)
// Space: O(1)

// greedy, kadane's algorithm
class Solution {
public:
    int maximumsSplicedArray(vector<int>& nums1, vector<int>& nums2) {
        const auto& modified_kadane = [](const auto& a, const auto& b) {
            int result = 0, curr = 0;
            for (int i = 0; i < size(a); ++i) {
                curr = max(curr + (b[i] - a[i]), 0);
                result = max(result, curr);
            }
            return accumulate(cbegin(a), cend(a), 0) + result;
        };

        return max(modified_kadane(nums1, nums2), modified_kadane(nums2, nums1));
    }
};

kamyu-c-maximum-score-using-exactly-k-pa:
// Time:  O(n * m * k)
// Space: O(min(n, m) * k)

// dp
class Solution {
public:
    long long maxScore(vector<int>& nums1, vector<int>& nums2, int k) {
        static const auto& NEG_INF = numeric_limits<int64_t>::min();

        if (size(nums1) < size(nums2)) {
            swap(nums1, nums2);
        }
        vector<vector<int64_t>> dp(size(nums2) + 1, vector<int64_t>(k + 1, NEG_INF));
        for (int j = 0; j < size(dp); ++j) {
            dp[j][0] = 0;
        }
        vector<vector<int64_t>> new_dp(size(nums2) + 1, vector<int64_t>(k + 1, NEG_INF));
        for (int i = 0; i < size(nums1); ++i) {
            for (int j = 0; j < size(new_dp); ++j) {
                new_dp[j][0] = 0;
            }            
            for (int j = 0; j < size(nums2); ++j) {
                const auto& score = static_cast<int64_t>(nums1[i]) * nums2[j];
                const auto& mx = min({i + 1, j + 1, k});
                for (int c = 0; c < mx; ++c) {
                    new_dp[j + 1][c + 1] = max({
                        new_dp[j][c + 1],
                        dp[j + 1][c + 1],
                        dp[j][c] + score
                    });
                }
            }
            swap(dp, new_dp);
        }
        return dp.back().back();
    }
};

// Time:  O(n * m * k)
// Space: O(n * m)
class Solution2 {
public:
    long long maxScore(vector<int>& nums1, vector<int>& nums2, int k) {
        static const auto& NEG_INF = numeric_limits<int64_t>::min();

        vector<vector<int64_t>> dp(size(nums1), vector<int64_t>(size(nums2), NEG_INF));
        vector<vector<int64_t>> new_dp(size(nums1), vector<int64_t>(size(nums2), NEG_INF));
        for (int c = 0; c < k; ++c) {
            for (int i = c; i < size(nums1); ++i) {
                for (int j = c; j < size(nums2); ++j) {
                    new_dp[i][j] = max({
                        j - 1 >= c ? new_dp[i][j - 1] : NEG_INF,
                        i - 1 >= c ? new_dp[i - 1][j] : NEG_INF,
                        (c ? dp[i - 1][j - 1] : 0) + static_cast<int64_t>(nums1[i]) * nums2[j]
                    });
                }
            }
            swap(dp, new_dp);
        }
        return dp.back().back();
    }
};

kamyu-c-maximum-score-with-co-prime-elem:
// Time:  O(n + rlogr)
// Space: O(r)

// dp, number theory, mobius function, principle of inclusion-exclusion
class Solution {
public:
    int maxScore(vector<int>& nums, int maxVal) {
        const auto& linear_sieve_of_eratosthenes = [](int n) {  // Time: O(n), Space: O(n)
            vector<int> spf(n + 1, -1);
            vector<int> primes;
            for (int i = 2; i <= n; ++i) {
                if (spf[i] == -1) {
                    spf[i] = i;
                    primes.emplace_back(i);
                }
                for (const auto& p : primes) {
                    if (i * p > n || p > spf[i]) {
                        break;
                    }
                    spf[i * p] = p;
                }
            }
            return spf;
        };

        // https://www.geeksforgeeks.org/program-for-mobius-function-set-2/
        const auto& mobius = [](const auto& spf) {  // Time: O(n), Space: O(n)
            vector<int> mu(size(spf));
            for (int i = 1; i < size(mu); ++i) {
                mu[i] = i == 1 ? 1 : (spf[i / spf[i]] == spf[i] ? 0 :  -mu[i / spf[i]]);
            }
            return mu;
        };

        const auto& mx = max(ranges::max(nums), maxVal);
        const auto& spf = linear_sieve_of_eratosthenes(mx);
        const auto& mu = mobius(spf);
        vector<int> cnt(mx + 1);
        for (const auto& x : nums) {
            ++cnt[x];
        }
        vector<int> multiple_cnt(mx + 1);
        for (int i = 1; i <= mx; ++i) {
            for (int j = i; j <= mx; j += i) {
                multiple_cnt[i] += cnt[j];
            }
        }
        vector<int> coprime_cnt(mx + 1);
        for (int i = 1; i <= mx; ++i) {
            if (!mu[i] * multiple_cnt[i]) {
                continue;
            }
            for (int j = i; j <= mx; j += i) {
                coprime_cnt[j] += mu[i] * multiple_cnt[i];
            }
        }
        int result = 0;
        for (int i = 1; i <= mx; ++i) {
            const int c = size(nums) - coprime_cnt[i];
            if (cnt[i]) {
                result = max(result, i - ((i != 1) ? (c - 1) : 0));
            } else if (i <= maxVal) {
                result = max(result, i - max(c, 1));
            }
        }
        return result;
    }
};

kamyu-c-maximum-score-words-formed-by-le:
// Time:  O(n * 2^n)
// Space: O(n)

class Solution {
public:
    int maxScoreWords(vector<string>& words, vector<char>& letters, vector<int>& score) {
        unordered_map<char, int> letter_count;
        vector<unordered_map<char, int>> word_counts(words.size());
        vector<int> word_scores(words.size());
        for (const auto& c : letters) {
            ++letter_count[c];
        }
        for (int i = 0; i < words.size(); ++i) {
            for (const auto& c : words[i]) {
                ++word_counts[i][c];
                word_scores[i] += score[c - 'a'];
            }
        }
        int result = 0;
        backtracking(words, word_scores, word_counts, 0, 0, &letter_count, &result);
        return result;
    }

private:
    void backtracking(const vector<string>& words,
                      const vector<int>& word_scores,
                      const vector<unordered_map<char, int>>& word_counts,
                      int curr,
                      int curr_score,
                      unordered_map<char, int> *letter_count,
                      int *result) {
        *result = max(*result, curr_score);
        for (int i = curr; i < words.size(); ++i) {
            if (any_of(word_counts[i].cbegin(), word_counts[i].cend(),
                       [&letter_count](const auto& x) {
                           return (*letter_count)[x.first] < x.second;
                       })) {
                continue;
            }
            for (const auto& [k, v] : word_counts[i]) {
                (*letter_count)[k] -= v;
            }
            backtracking(words, word_scores, word_counts,
                         i + 1, curr_score + word_scores[i], letter_count, result);
            for (const auto& [k, v] : word_counts[i]) {
                (*letter_count)[k] += v;
            }
        }
    }
};

kamyu-c-maximum-segment-sum-after-remova:
// Time:  O(n)
// Space: O(n)

// union find
class Solution {
public:
    vector<long long> maximumSegmentSum(vector<int>& nums, vector<int>& removeQueries) {
        vector<long long> result(size(nums));
        vector<bool> lookup(size(nums));
        UnionFind uf(nums);
        for (int i = size(removeQueries) - 1; i >= 1; --i) {
            const int q = removeQueries[i];
            lookup[q] = true;
            if (q - 1 >= 0 && lookup[q - 1]) {
                uf.union_set(q - 1, q);
            }
            if (q + 1 < size(lookup) && lookup[q + 1]) {
                uf.union_set(q, q + 1);
            }
            result[i - 1] = max(result[i], uf.total(q));
        }
        return result;
    }

private:
    class UnionFind {
    public:
        UnionFind(const vector<int>& nums)
         : set_(size(nums))
         , rank_(size(nums))
         , size_(cbegin(nums), cend(nums))  {
            iota(set_.begin(), set_.end(), 0);
        }

        int find_set(int x) {
           if (set_[x] != x) {
               set_[x] = find_set(set_[x]);  // Path compression.
           }
           return set_[x];
        }

        bool union_set(int x, int y) {
            x = find_set(x), y = find_set(y);
            if (x == y) {
                return false;
            }
            if (rank_[x] > rank_[y]) {
                swap(x, y);
            }
            set_[x] = y;  // Union by rank.
            if (rank_[x] == rank_[y]) {
                ++rank_[y];
            }
            size_[y] += size_[x];
            return true;
        }

        long long total(int x) {
            return size_[find_set(x)];
        }

    private:
        vector<int> set_;
        vector<int> rank_;
        vector<long long> size_;
    };
};

// Time:  O(nlogn)
// Space: O(n)
// prefix sum, bst
class Solution2 {
public:
    vector<long long> maximumSegmentSum(vector<int>& nums, vector<int>& removeQueries) {
        set<int> removed_idxs = {-1, static_cast<int>(size(nums))};
        vector<long long> prefix(size(nums) + 1);
        for (int i = 0; i < size(nums); ++i) {
            prefix[i + 1] = prefix[i] + nums[i];
        }
        multiset<long long> segments = {prefix.back()};
        vector<long long> result;
        for (const auto& q : removeQueries) {
            const auto it = removed_idxs.emplace(q).first;
            const int left = *prev(it), right = *next(it);
            segments.erase(segments.find(prefix[right] - prefix[left + 1]));
            segments.emplace(prefix[q] - prefix[left + 1]);
            segments.emplace(prefix[right] - prefix[q + 1]);
            result.emplace_back(*rbegin(segments));
        }
        return result;
    }
};

kamyu-c-maximum-side-length-of-a-square-:
// Time:  O(m * n * log(min(m, n)))
// Space: O(m * n)

class Solution {
public:
    int maxSideLength(vector<vector<int>>& mat, int threshold) {
        vector<vector<int>> dp(mat.size() + 1, vector<int>(mat[0].size() + 1));
        for (int i = 1; i < mat.size() + 1; ++i) {
            for (int j  = 1; j < mat[0].size() + 1; ++j) {
                dp[i][j] = dp[i - 1][j] + dp[i][j - 1] - dp[i - 1][j - 1] + mat[i - 1][j - 1];
            }
        }

        int left = 0, right = min(mat.size(), mat[0].size());
        while (left <= right) {
            const auto mid = left + (right - left) / 2;
            if (!check(dp, mid, threshold)) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }
        return right;
    }

private:
    bool check(const vector<vector<int>>& dp, int mid, int threshold) {
        for (int i = mid; i < dp.size(); ++i) {
            for (int j = mid; j < dp[0].size(); ++j) {
                if (dp[i][j] - dp[i-mid][j] - dp[i][j-mid] + dp[i-mid][j-mid] <= threshold) {
                    return true;
                }
            }
        }
        return false;
    }
};

