        }
        const auto& mx = single;
        assert(f(mx).second <= m);
        const auto& x = binary_search(static_cast<int64_t>(1), mx, [&](const auto& x) {
            return f(x).second <= m;
        });
        return f(x).first + static_cast<int64_t>(m) * x;
    }
