// Time:  O(n + qlogn)
// Space: O(n)

// segment tree
class Solution {
public:
    int maximumSumSubsequence(vector<int>& nums, vector<vector<int>>& queries) {
        static const int MOD = 1e9 + 7;
        enum {L0R0, L1R0, L0R1, L1R1};

        const auto& build = [&](int i) {
            return vector<int64_t>{max(nums[i], 0), 0, 0, 0};
        };

        const auto& update = [] (const auto& c) {
            return c;
        };

        const auto& query = [&] (const auto& x, const auto& y) {
            if (empty(x)) {
                return y;
            }
            if (empty(y)) {
                return x;
            }
            return vector<int64_t>{
                max({x[L0R1] + y[L1R0], x[L0R0] + y[L1R0], x[L0R1] + y[L0R0]}),
                max({x[L1R1] + y[L1R0], x[L1R0] + y[L1R0], x[L1R1] + y[L0R0]}),
                max({x[L0R1] + y[L1R1], x[L0R0] + y[L1R1], x[L0R1] + y[L0R1]}),
                max({x[L1R1] + y[L1R1], x[L1R0] + y[L1R1], x[L1R1] + y[L0R1]})
            };
        };

        SegmentTree<vector<int64_t>> st(size(nums), build, update, query);
        int result = 0;
        for (const auto& q : queries) {
            st.update(q[0], vector<int64_t>{max(q[1], 0), 0, 0, 0});
            result = (result + ranges::max(st.tree[1])) % MOD;
        }
        return result;
    }

private:
    // Template:
    // https://github.com/kamyu104/LeetCode-Solutions/blob/master/C++/booking-concert-tickets-in-groups.cpp
    template <typename T>
    class SegmentTree {
     public:
        explicit SegmentTree(
            int N,
            const function<T(const int&)>& build_fn,
            const function<T(const T&)>& update_fn,
            const function<T(const T&, const T&)>& query_fn)
          : tree(N > 1 ? 1 << (__lg(N - 1) + 2) : 2),
            base(N > 1 ? 1 << (__lg(N - 1) + 1) : 1),
            build_fn_(build_fn),
            query_fn_(query_fn),
            update_fn_(update_fn) {

            for (int i = base; i < base + N; ++i) {
                tree[i] = build_fn_(i - base);
            }
            for (int i = base - 1; i >= 1; --i) {
                tree[i] = query_fn_(tree[i << 1], tree[(i << 1) + 1]);
            }
        }

        void update(int i, const T& h) {
            int x = base + i;
            tree[x] = update_fn_(h);
            while (x > 1) {
                x >>= 1;
                tree[x] = query_fn_(tree[x << 1], tree[(x << 1) + 1]);
            }
        }

        T query(int L, int R) {
            L += base;
            R += base;
            T left, right;
            for (; L <= R; L >>= 1, R >>= 1) {
                if (L & 1) {
                    left = query_fn_(left, tree[L]);
                    ++L;
                }
                if ((R & 1) == 0) {
                    right = query_fn_(tree[R], right);
                    --R;
                }
            }
            return query_fn_(left, right);
        }

        vector<T> tree;
        int base;

    private:
        const function<T(const int&)> build_fn_;
        const function<T(const T&)> update_fn_;
        const function<T(const T&, const T&)> query_fn_;
    };
};

kamyu-c-maximum-sum-of-three-numbers-div:
// Time:  O(n)
// Space: O(1)

// sort, math
class Solution {
public:
    int maximumSum(vector<int>& nums) {
        const auto& add = [](auto& arr, int x) {
            for (int i = 0; i < size(arr); ++i) {
                if (x > arr[i]) {
                    swap(arr[i], x);
                }
            }
            if (size(arr) != 3) {
                arr.emplace_back(x);
            }
        };

        vector<vector<int>> group(3);
        for (const auto& x : nums) {
            add(group[x % 3], x);
        }
        int result = 0;
        for (auto& g : group) {
            if (size(g) == 3) {
                result = max(result, accumulate(cbegin(g), cend(g), 0));
            }
        }
        if (!empty(group[0]) && !empty(group[1]) && !empty(group[2])) {
            result = max(result, group[0][0] + group[1][0] + group[2][0]);
        }
        return result;
    }
};

// Time:  O(nlogn)
// Space: O(n)
// sort, math
class Solution2 {
public:
    int maximumSum(vector<int>& nums) {
        vector<vector<int>> group(3);
        for (const auto& x : nums) {
            group[x % 3].emplace_back(x);
        }
        int result = 0;
        for (auto& g : group) {
            sort(begin(g), end(g), greater<int>());
            if (size(g) >= 3) {
                result = max(result, accumulate(cbegin(g), cbegin(g) + 3, 0));
            }
        }
        if (!empty(group[0]) && !empty(group[1]) && !empty(group[2])) {
            result = max(result, group[0][0] + group[1][0] + group[2][0]);
        }
        return result;
    }
};

kamyu-c-maximum-sum-of-two-non-overlappi:
// Time:  O(n)
// Space: O(1)

class Solution {
public:
    int maxSumTwoNoOverlap(vector<int>& A, int L, int M) {
        for (int i = 1; i < A.size(); ++i) {
            A[i] += A[i - 1];
        }
        int result = A[L + M - 1], L_max = A[L - 1], M_max = A[M - 1];
        for (int i = L + M; i < A.size(); ++i) {
            L_max = max(L_max, A[i - M] - A[i - L - M]);
            M_max = max(M_max, A[i - L] - A[i - L - M]);
            result = max(result,
                         max(L_max + A[i] - A[i - M],
                             M_max + A[i] - A[i - L]));
        }
        return result;
    }
};

kamyu-c-maximum-sum-queries-1qhjdlx:
// Time:  O(nlogn + mlogm + mlogn)
// Space: O(n + m)

// sort, mono stack, binary search
class Solution {
public:
    vector<int> maximumSumQueries(vector<int>& nums1, vector<int>& nums2, vector<vector<int>>& queries) {
        vector<pair<int, int>> pairs;
        for (int i = 0; i < size(nums1); ++i) {
            pairs.emplace_back(nums1[i], nums2[i]);
        }
        sort(begin(pairs), end(pairs));
        vector<tuple<int, int, int>> sorted_queries;
        for (int i = 0; i < size(queries); ++i) {
            sorted_queries.emplace_back(queries[i][0], queries[i][1], i);
        }
        sort(rbegin(sorted_queries), rend(sorted_queries));
        vector<int> result(size(queries));
        vector<pair<int, int>> stk;
        for (const auto& [x, y, i] : sorted_queries) {
            while (!empty(pairs) && pairs.back().first >= x) {
                const auto [a, b] = pairs.back(); pairs.pop_back();
                while (!empty(stk) && stk.back().second <= a + b) {
                    stk.pop_back();
                }
                if (empty(stk) || stk.back().first < b) {
                    stk.emplace_back(b, a + b);
                }
            }
            const auto it = lower_bound(cbegin(stk), cend(stk), pair(y, 0));
            result[i] = it != cend(stk) ? it->second : -1;
        }
        return result;
    }
};

kamyu-c-maximum-sum-score-of-array-0odir:
// Time:  O(n)
// Space: O(1)

// prefix sum, math
class Solution {
public:
    long long maximumSumScore(vector<int>& nums) {
        int64_t result = numeric_limits<int>::min();
        int64_t prefix = 0, suffix = 0;
        for (int left = 0, right = size(nums) - 1; left < size(nums); ++left, --right) {
            prefix += nums[left];
            suffix += nums[right];
            result = max({result, prefix, suffix});
        }
        return result;
    }
};

// Time:  O(n)
// Space: O(1)
// prefix sum
class Solution2 {
public:
    long long maximumSumScore(vector<int>& nums) {
        const int64_t total = accumulate(cbegin(nums), cend(nums), 0ll);
        int64_t result = numeric_limits<int>::min();
        int64_t prefix = 0;
        for (const auto& x : nums) {
            prefix += x;
            result = max({result, prefix, total - prefix + x});
        }
        return result;
    }
};

kamyu-c-maximum-sum-with-at-most-k-eleme:
// Time:  O(n * m)
// Space: O(1)

// greedy, quick select
class Solution {
public:
    long long maxSum(vector<vector<int>>& grid, vector<int>& limits, int k) {
        vector<int> candidates;
        for (int i = 0; i < size(grid); ++i) {
            int cnt = min(k, limits[i]);
            if (cnt - 1 >= 0) {
                nth_element(begin(grid[i]), begin(grid[i]) + (cnt - 1), end(grid[i]), greater<int>());
                while (cnt) {
                    candidates.emplace_back(grid[i][--cnt]);
                }
           }
        }
        int64_t result = 0;
        if (k - 1 >= 0) {
            nth_element(begin(candidates), begin(candidates) + (k - 1), end(candidates), greater<int>());
            result = accumulate(cbegin(candidates), cbegin(candidates) + k, 0ll);
        }
        return result;
    }
};

