kamyu-c-maximum-swap-1vyggfc:
// Time:  O(logn), logn is the length of the number string
// Space: O(logn)

class Solution {
public:
    int maximumSwap(int num) {
        string digits = to_string(num);
        int left = 0, right = 0;
        int max_idx = digits.length() - 1;
        for (int i = digits.length() - 1; i >= 0; --i) {
            if (digits[i] > digits[max_idx]) {
                max_idx = i;
            } else if (digits[max_idx] > digits[i]) {
                left = i;
                right = max_idx;
            }
        }
        swap(digits[left], digits[right]);
        return stoi(digits);
    }
};

kamyu-c-maximum-tastiness-of-candy-baske:
// Time:  O(nlogr), r = max(price)-min(price)
// Space: O(1)

// binary search, greedy
class Solution {
public:
    int maximumTastiness(vector<int>& price, int k) {
        const auto& check = [&](int x) {  // find max cnt if smallest absolute difference >= x
            int cnt = 0, prev = 0;
            for (int i = 0, j = 0; i < size(price); ++i) {
                if (prev && price[i] - prev < x) {
                    continue;
                }
                if (++cnt == k) {
                    break;
                }
                prev = price[i];
            }
            return cnt >= k;
        };

        sort(begin(price), end(price));
        int left = 1, right = price.back() - price.front();
        while (left <= right) {
            const int mid = left + (right - left) / 2;
            if (!check(mid)) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }
        return right;
    }
};

kamyu-c-maximum-team-size-with-overlappi:
// Time:  O(nlogn)
// Space: O(n)

// sort, binary search
class Solution {
public:
    int maximumTeamSize(vector<int>& startTime, vector<int>& endTime) {
        vector<int> sorted_start(startTime);
        ranges::sort(sorted_start);
        vector<int> sorted_end(endTime);
        ranges::sort(sorted_end);
        int result = 0;
        for (int i = 0; i < size(startTime); ++i) {
            const int left = distance(cbegin(sorted_end), lower_bound(cbegin(sorted_end), cend(sorted_end), startTime[i]));
            const int right = distance(cbegin(sorted_start), upper_bound(cbegin(sorted_start), cend(sorted_start), endTime[i]));
            result = max(result, right - left);
        }
        return result;
    }
};

kamyu-c-maximum-total-area-occupied-by-p:
// Time:  O(h)
// Space: O(h)

// line sweep, difference array
class Solution {
public:
    long long maxArea(int height, vector<int>& positions, string directions) {
        vector<int> diff(2 * height + 1);
        for (int i = 0; i < size(positions); ++i) {
            if (directions[i] == 'U') {
                --diff[height - positions[i]];
                ++diff[(height - positions[i]) + height];
            } else {
                ++diff[positions[i]];
                --diff[positions[i] + height];
            }
        }
        int64_t total = accumulate(cbegin(positions), cend(positions), 0ll);
        int64_t result = total;
        int cnt = count(cbegin(directions), cend(directions), 'U');
        for (int t = 1; t < size(diff); ++t) {
            total += -(static_cast<int32_t>(size(directions)) - cnt) + cnt;
            result = max(result, total);
            cnt += diff[t];
        }
        return result;
    }
};

// Time:  O(nlogn)
// Space: O(n)
// sort, line sweep, difference array
class Solution2 {
public:
    long long maxArea(int height, vector<int>& positions, string directions) {
        unordered_map<int, int> diff;
        for (int i = 0; i < size(positions); ++i) {
            if (directions[i] == 'U') {
                --diff[height - positions[i]];
                ++diff[(height - positions[i]) + height];
            } else {
                ++diff[positions[i]];
                --diff[positions[i] + height];
            }
        }
        int64_t total = accumulate(cbegin(positions), cend(positions), 0ll);
        int64_t result = total;
        int cnt = count(cbegin(directions), cend(directions), 'U');
        int prev = 0;
        vector<pair<int, int>> sorted_diff(cbegin(diff), cend(diff));
        sort(begin(sorted_diff), end(sorted_diff));
        for (const auto& [t, d] : sorted_diff) {
            total += static_cast<int64_t>(t - prev) * (-(static_cast<int32_t>(size(directions)) - cnt) + cnt);
            result = max(result, total);
            cnt += d;
            prev = t;
        }
        return result;
    }
};

kamyu-c-maximum-total-beauty-of-the-gard:
// Time:  O(nlogn)
// Space: O(1)

// sort, prefix sum, greedy, two pointers, improved from solution3
class Solution {
public:
    long long maximumBeauty(vector<int>& flowers, long long newFlowers, int target, int full, int partial) {
        const auto it = partition(begin(flowers), end(flowers), [&target](int x) { return x < target; });
        sort(begin(flowers), it);
        const long long n = distance(begin(flowers), it);
        long long prefix = 0, suffix = accumulate(begin(flowers), it, 0ll);
        long long result = 0;
        for (long long right = 0, left = 0; right <= n; ++right) {
            if (right) {
                suffix -= flowers[right - 1];
            }
            const auto total = newFlowers - (static_cast<long long>(n - right) * target - suffix);
            if (total < 0) {
                continue;
            }
            while (!(left == right || (left && (total + prefix) / left <= flowers[left]))) {
                prefix += flowers[left++];
            }
            const auto mn = min(left ? (total + prefix) / left : 0ll, static_cast<long long>(target) - 1);
            result = max(result, mn * partial + (static_cast<long long>(size(flowers)) - right) * full);
        }
        return result;
    }
};

// Time:  O(nlogn)
// Space: O(1)
// sort, prefix sum, greedy, two pointers, improved from solution4
class Solution2 {
public:
    long long maximumBeauty(vector<int>& flowers, long long newFlowers, int target, int full, int partial) {
        const auto it = partition(begin(flowers), end(flowers), [&target](int x) { return x < target; });
        sort(begin(flowers), it);
        const long long n = distance(begin(flowers), it);
        vector<long long> prefix(n + 1);
        for (int i = 0; i < n; ++i) {
            prefix[i + 1] = prefix[i] + flowers[i];
        }
        long long result = 0, suffix = 0;
        for (long long right = n, left = n; right >= 0; --right) {
            if (right != n) {
                suffix += flowers[right];
            }
            const auto total = newFlowers - (static_cast<long long>(n - right) * target - suffix);
            if (total < 0) {
                break;
            }
            left = min(left, right);
            while (!(left == 0 || (prefix[left] - prefix[left - 1]) * left - prefix[left] <= total)) {
                --left;
            }
            const auto mn = min(left ? (total + prefix[left]) / left : 0ll, static_cast<long long>(target) - 1);
            result = max(result, mn * partial + (static_cast<long long>(size(flowers)) - right) * full);
        }
        return result;
    }
};

// Time:  O(nlogn)
// Space: O(n)
// sort, prefix sum, greedy, binary search
class Solution3 {
public:
    long long maximumBeauty(vector<int>& flowers, long long newFlowers, int target, int full, int partial) {
        const auto& check = [](const auto& prefix, const auto& total, auto x) {
            return x && (total + prefix[x]) / x <= prefix[x + 1] - prefix[x];
        };
        const auto& binary_search = [&check](const auto& prefix, const auto& total, auto left, auto right) {
            while (left <= right) {
                const auto mid = left + (right - left) / 2;
                if (check(prefix, total, mid)) {
                    right = mid - 1;
                } else {
                    left = mid + 1;
                }
            }
            return left;
        };
        const auto it = partition(begin(flowers), end(flowers), [&target](int x) { return x < target; });
        sort(begin(flowers), it);
        const long long n = distance(begin(flowers), it);
        vector<long long> prefix(n + 1);
        for (int i = 0; i < n; ++i) {
            prefix[i + 1] = prefix[i] + flowers[i];
        }
        long long suffix = accumulate(begin(flowers), it, 0ll);
        long long result = 0;
        for (long long right = 0; right <= n; ++right) {
            if (right) {
                suffix -= flowers[right - 1];
            }
            const auto total = newFlowers - (static_cast<long long>(n - right) * target - suffix);
            if (total < 0) {
                continue;
            }
            const auto left = binary_search(prefix, total, 0, right - 1);
            const auto mn = min(left ? (total + prefix[left]) / left : 0ll, static_cast<long long>(target) - 1);
            result = max(result, mn * partial + (static_cast<long long>(size(flowers)) - right) * full);
        }
        return result;
    }
};

// Time:  O(nlogn)
// Space: O(n)
// sort, prefix sum, greedy, binary search
class Solution4 {
public:
    long long maximumBeauty(vector<int>& flowers, long long newFlowers, int target, int full, int partial) {
        const auto& check = [](const auto& prefix, const auto& total, auto x) {
            return (prefix[x] - prefix[x - 1]) * x - prefix[x] <= total;
        };
        const auto& binary_search_right = [&check](const auto& prefix, const auto& total, auto left, auto right) {
            while (left <= right) {
                const auto mid = left + (right - left) / 2;
                if (!check(prefix, total, mid)) {
                    right = mid - 1;
                } else {
                    left = mid + 1;
                }
            }
            return right;
        };
        const auto it = partition(begin(flowers), end(flowers), [&target](int x) { return x < target; });
        sort(begin(flowers), it);
        const long long n = distance(begin(flowers), it);
        vector<long long> prefix(n + 1);
        for (int i = 0; i < n; ++i) {
            prefix[i + 1] = prefix[i] + flowers[i];
        }
        long long result = 0, suffix = 0;
        for (long long right = n; right >= 0; --right) {
            if (right != n) {
                suffix += flowers[right];
            }
            const auto total = newFlowers - (static_cast<long long>(n - right) * target - suffix);
            if (total < 0) {
                break;
            }
            const auto left = binary_search_right(prefix, total, 1, right);
            const auto mn = min(left ? (total + prefix[left]) / left : 0ll, static_cast<long long>(target) - 1);
            result = max(result, mn * partial + (static_cast<long long>(size(flowers)) - right) * full);
        }
        return result;
    }
};

kamyu-c-maximum-total-damage-with-spell-:
// Time:  O(nlogn)
// Space: O(1)

// sort, dp, two pointers, sliding window, deque
class Solution {
public:
    long long maximumTotalDamage(vector<int>& power) {
        static const int DIST = 2;

        sort(begin(power), end(power));
        deque<pair<int, int64_t>> dp;
        int64_t mx = 0;
        for (const auto& x: power) {
            if (!empty(dp) && dp.back().first == x) {
                dp.back().second += x;
                continue;
            }
            while (!empty(dp) && dp.front().first + DIST < x) {
                mx = max(mx, dp.front().second);
                dp.pop_front();
            }
            dp.emplace_back(x, mx + x);
        }
        return max_element(cbegin(dp), cend(dp), [](const auto& a, const auto& b) {
            return a.second < b.second;
        })->second;
    }
};
